+            case TEXT_EMBEDDING -> {
+                return embeddingProviders.contains(provider);
+            }
+            default -> {
+                return false;
+            }
+        }
+    }
+
+    public static boolean providerAllowsEndpointTypeForTask(
+        AzureAiStudioProvider provider,
+        TaskType taskType,
