+        if (vector.min() >= min && vector.max() < max) {
+            if (min == 0) {
+                vector.incRef();
+                return vector.asBlock();
+            }
+            return lookupVectorInRange(vector).asBlock();
+        }
+        return lookupVectorMaybeInRange(vector);
+    }
