+                            continue;
+                        }
+                        if (first < 0) {
+                            first = v - min;
+                            continue;
+                        }
+                        if (started == false) {
+                            builder.beginPositionEntry();
+                            builder.appendInt(first);
+                            started = true;
+                        }
+                        builder.appendInt(v - min);
+                    }
+                    p++;
+                    if (started) {
+                        builder.endPositionEntry();
+                        continue;
+                    }
+                    if (first < 0) {
+                        builder.appendNull();
+                        continue;
+                    }
+                    builder.appendInt(first);
+                }
+                return builder.build();
+            }
+        }
+
+        @Override
+        public void close() {
+            block.decRef();
+        }
+
+        @Override
+        public String toString() {
+            return "AscendingSequence[" + p + "/" + block.getPositionCount() + "]";
+        }
+    }
+
+    @Override
+    public void close() {}
